create table eba_demo_dg_customers (
    customer_id   number
        generated by default on null as identity
    not null enable,
    full_name     varchar2(255 byte) not null enable,
    email_address varchar2(255 byte) not null enable
);

alter table eba_demo_dg_customers add constraint eba_demo_dg_cust_email_u unique ( email_address )
    using index enable;

alter table eba_demo_dg_customers
    add constraint eba_demo_dg_cust_pk primary key ( customer_id )
        using index enable;


